            if (!this.session || !this.collecting || !this.current(generation)) return;
            const age = Date.now() - position.timestamp;
            // Drop old/future/invalid GPS readings; never persist or replay a coordinate backlog.
            if (
              !Number.isFinite(age) ||
              age > 25_000 ||
              age < -5_000 ||
              !Number.isFinite(position.coords.latitude) ||
              Math.abs(position.coords.latitude) > 90 ||
              !Number.isFinite(position.coords.longitude) ||
              Math.abs(position.coords.longitude) > 180 ||
              !Number.isFinite(position.coords.accuracy) ||
              position.coords.accuracy < 0
            )
              return;
            const session = this.session;
            const accepted = await this.api.mutate<{ version: number; acceptedSequence: number }>(
              'POST',
              '/v1/tracking/sessions/' + idPath(session.id) + '/points',
              {
                expectedVersion: session.version,
                deviceId: this.deviceId,
                sequence: session.sequence + 1,
                latitude: position.coords.latitude,
                longitude: position.coords.longitude,
                accuracy: position.coords.accuracy,
                capturedAt: new Date(position.timestamp).toISOString(),
              },
              signal,
            );
            if (!this.current(generation) || this.session !== session) return;
            session.version = accepted.version;
            session.sequence = accepted.acceptedSequence;
            this.publish('مشاركة الموقع نشطة أثناء استخدام التطبيق.');
          }).catch:

condition:commit((s) => {
            const current = client(s, c.id);
            A.assert(
              current && !current.doNotContact,
              'لا يمكن التواصل مع هذا العميل؛ تغيّر إذنه أو إسناده.',
            );
            A.assert(!s.session.offline, 'أنه وضع دون اتصال قبل الإرسال.');
            s.messages.push({
              id: A.id('msg'),
              clientId: c.id,
              from: 'rep',
              text,
              at: now(),
              read: false,
            });
            notify(s, 'client', 'رسالة من مندوبك', text.slice(0, 100), {
              clientId: c.id,
            });
          }, 'إرسال رسالة داخل العرض المحلي') !== false

condition:commit((s) => {
            const q = ownQuotes(s).find((x) => x.id === el.dataset.id);
            A.assert(
              q && ['draft', 'revision_requested'].includes(q.status),
              'تغيّرت حالة العرض؛ افتح النسخة الحالية.',
            );
            A.assert(
              quoteFingerprint(q) === quoteFingerprint(seen),
              'تغيّر نطاق العرض في نافذة أخرى؛ راجعه قبل الإرسال.',
            );
            const error = quoteValidation(s, q);
            A.assert(!error, error);
            A.assert(!s.session.offline, 'العرض محفوظ؛ أنهِ وضع دون اتصال قبل إرساله.');
            if (!q.scopeSnapshot) {
              q.items = scopeItems(q.items, s);
              q.scopeSnapshot = {
                version: q.version || 1,
                capturedAt: now(),
                items: clone(q.items),
                terms: q.terms,
                proposedDuration: q.proposedDuration || '',
                paymentWishes: q.paymentWishes || '',
              };
            }
            if (quoteMath(q).percent > 15 && !quoteApproval(s, q)) {
              addDiscountApproval(s, q);
              held = true;
              return;
            }
            q.status = 'sent';
            q.revisionRequest = '';
            q.sentAt = now();
            q.updatedAt = now();
            bindQuoteToVisit(s, q);
            notify(s, 'client', 'عرض سعر بانتظارك', q.title, {
              clientId: q.clientId,
            });
            const o = ownOpps(s).find((row) => row.id === q.opportunityId);
            if (o && ['new', 'qualified'].includes(o.stage)) {
              o.stage = 'proposal';
              o.probability = 55;
            }
            sent = true;
          }, 'مراجعة نسخة العرض الحالية قبل الإرسال') === false

catalog
    .filter((service) => service.active !== false)
    .map((service): Recommendation<T> => {
      let score = 0;
      const reasons: string[] = [];
      const name = (service.id + ' ' + service.category + ' ' + service.title).toLowerCase();
      for (const [key, triggers] of rules) {
        if (name.includes(key) || service.id.includes(key)) {
          const hits = triggers.filter((word) => combined.includes(word));
          score += hits.length * 2;
          if (hits.length) reasons.push('يتوافق مع إجاباتك عن: ' + hits.join('، '));
        }
      }
      for (const tag of service.recommendationTags || []) {
        if (combined.includes(tag.toLowerCase())) {
          score += 3;
          reasons.push('مرتبط بهدف: ' + tag);
        }
      }
      return { ...service, score, reasons: reasons.slice(0, 2) };
    })
    .filter

